"""Offline schemas against reports generated by the production C# core."""
import importlib.util
import json
from pathlib import Path
from jsonschema import Draft202012Validator

root = Path(__file__).parents[1]
spec = importlib.util.spec_from_file_location("centers_contract_cli", root / "cli/sp2build.py")
cli = importlib.util.module_from_spec(spec)
spec.loader.exec_module(cli)
schema = cli.contracts_module().output_schema("craft.centers")
Draft202012Validator.check_schema(schema)
reports = []
directory = root / "tests/artifacts/centers-0.4.0"
for name in ("summary", "contributors", "partial", "empty", "comparison", "not-comparable", "with-images"):
    data = json.loads((directory / (name + ".json")).read_text(encoding="utf-8-sig"))
    errors = list(Draft202012Validator(schema).iter_errors(data))
    reports.append({"name": name, "pass": not errors, "errors": [str(e) for e in errors]})
input_schema = cli.schema("craft.centers")
for name, request, valid in [
    ("default", {}, True), ("images", {"images": True}, True),
    ("focus explicit", {"focusSelector": {"kind": "parts", "partIds": [1, 2]}}, True),
    ("focus assembly", {"focusSelector": {"kind": "assembly", "rootPartId": 4}}, True),
    ("ambiguous focus", {"focus": "selected", "focusSelector": {"kind": "parts", "partIds": [1]}}, False),
    ("bad limit", {"limit": True}, False), ("old frame", {"frame": {"kind": "part"}}, False),
    ("tiny image", {"images": True, "resolution": {"width": 128}}, False),
    ("baseline object bypass", {"baseline": {}}, False),
]:
    errors = list(Draft202012Validator(input_schema).iter_errors(request))
    reports.append({"name": name, "pass": bool(not errors) == valid})
(directory / "contract-validation.json").write_text(json.dumps(reports, ensure_ascii=False, indent=2), encoding="utf-8")
failed = [r for r in reports if not r["pass"]]
if failed:
    raise SystemExit(json.dumps(failed, ensure_ascii=False, indent=2))
print(f"Centers contract checks passed: {len(reports)}")
